254	    /**
255	     * 스냅샷 후 현재 목록 순서대로 sort_no 를 n..1 로 재부여 (중간 빈 번호 제거).
256	     *
257	     * @return int 갱신한 행 수
258	     */
259	    public static function rebalanceSortNos(): int
260	    {
261	        $db = DB::getInstance();
262	        $db->beginTransaction();
263	        try {
264	            self::snapshotSortNosToUndo($db);
265	            $stmt = $db->query(
266	                'SELECT id FROM nb_works WHERE deleted_at IS NULL ORDER BY sort_no DESC, id DESC'
267	            );
268	            /** @var list<int|string> $ids */
269	            $ids = $stmt->fetchAll(PDO::FETCH_COLUMN);
270	            $cnt = count($ids);
271	            if ($cnt === 0) {
272	                $db->commit();
273	
274	                return 0;
275	            }
276	            $phase1 = $db->prepare(
277	                'UPDATE nb_works SET sort_no = :sn, updated_at = NOW() WHERE id = :id AND deleted_at IS NULL'
278	            );
279	            foreach ($ids as $id) {
280	                $i = (int) $id;
281	                $phase1->execute([':sn' => -$i, ':id' => $i]);
282	            }
283	            $v = $cnt;
284	            foreach ($ids as $id) {
285	                $phase1->execute([':sn' => $v, ':id' => (int) $id]);
286	                $v--;
287	            }
288	            $db->commit();
289	
290	            return $cnt;
291	        } catch (\Throwable $e) {
292	            $db->rollBack();
293	            throw $e;
294	        }
295	    }
