297	    /**
298	     * 마지막 rebalanceSortNos() 직전에 저장된 sort_no 로 되돌림 (스냅샷이 비어 있으면 0).
299	     *
300	     * @return int 복원 시도한 행 수(스냅샷 행 수)
301	     */
302	    public static function restoreSortNosFromUndo(): int
303	    {
304	        $db = DB::getInstance();
305	        self::ensureSortNoUndoTable($db);
306	        $stmt = $db->query('SELECT works_id, sort_no FROM nb_works_sort_no_undo');
307	        $pairs = $stmt->fetchAll(PDO::FETCH_ASSOC);
308	        if ($pairs === []) {
309	            return 0;
310	        }
311	        $db->beginTransaction();
312	        try {
313	            $phase = $db->prepare(
314	                'UPDATE nb_works SET sort_no = :sn, updated_at = NOW() WHERE id = :id AND deleted_at IS NULL'
315	            );
316	            foreach ($pairs as $r) {
317	                $wid = (int) $r['works_id'];
318	                $phase->execute([':sn' => -$wid, ':id' => $wid]);
319	            }
320	            foreach ($pairs as $r) {
321	                $phase->execute([
322	                    ':sn' => (int) $r['sort_no'],
323	                    ':id' => (int) $r['works_id'],
324	                ]);
325	            }
326	            $db->commit();
327	
328	            return count($pairs);
329	        } catch (\Throwable $e) {
330	            $db->rollBack();
331	            throw $e;
332	        }
333	    }
